#include <iostream>
#include <string>

struct Animal {
    virtual std::string name() const { return "Animal"; }
    std::string kind() const { return "animal"; }
    virtual ~Animal() = default;
};

struct Dog : Animal {
    std::string name() const override { return "Dog"; }
    std::string kind() const { return "dog"; }
};

void show(Animal a) { std::cout << a.name() << '\n'; }

int main() {
    Dog d;
    Animal* p = &d;
    std::cout << p->name() << ' ' << p->kind() << '\n';
    show(d);
}
